import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    strings = []
    for _ in range(n):
        try:
            s = next(iterator)
            strings.append(s)
        except StopIteration:
            break

    # Sort by length. If lengths are equal, the order doesn't strictly matter for length,
    # but we need to ensure the substring property holds.
    # Since a string can only be a substring of another if len(a) <= len(b),
    # sorting by length is the necessary first step.
    strings.sort(key=len)

    # Check if the sorted array satisfies the condition:
    # strings[i] must be a substring of strings[i+1] for all valid i.
    # Note: The problem says "all strings placed before it are its substrings".
    # If A is substring of B, and B is substring of C, then A is substring of C.
    # So checking adjacent pairs in the sorted-by-length list is sufficient.

    possible = True
    for i in range(n - 1):
        if strings[i] not in strings[i + 1]:
            possible = False
            break

    if possible:
        print("YES")
        for s in strings:
            print(s)
    else:
        print("NO")

if __name__ == "__main__":
    solve()
